import { toJsonSchema, validateSchema } from "./standard-schema.js";
/**
 * Define a {@link ChannelTool} with full type inference. The handler's `args` are
 * inferred from `parameters`, and `ctx` is the generic {@link ChannelToolContext}
 * ({@link Thread} + optional message/signal + application user + provider actor
 * + platform). Reach for
 * platform power via capability-gated `thread` methods (e.g.
 * `thread.getMessages()`, `thread.lookupUser(query)`).
 *
 * ```ts
 * const tool = defineChannelTool({
 *   name: "show_thing",
 *   description: "...",
 *   parameters: z.object({ id: z.string() }),
 *   async handler({ id }, { thread }) {  // `id` and `ctx` fully typed
 *     await thread.post(<Thing id={id} />);
 *     return "Displayed the thing.";
 *   },
 * });
 * ```
 */
export function defineChannelTool(tool) {
    return tool;
}
export function toAgentToolDescriptors(tools) {
    return tools.map((t) => ({
        name: t.name,
        description: t.description,
        parameters: toJsonSchema(t.parameters),
    }));
}
export const parseToolArgs = validateSchema;
export function stringifyHandlerResult(value) {
    if (value == null)
        return "";
    if (typeof value === "string")
        return value;
    return JSON.stringify(value);
}
